SELECT a FROM t INDEXED BY idx WHERE a = 1;

SELECT a FROM t NOT INDEXED WHERE a = 1;

SELECT x.a FROM main.t AS x INDEXED BY idx WHERE x.a = 1;

SELECT t.a, u.b FROM t NOT INDEXED JOIN u INDEXED BY idx_u ON t.a = u.b;

UPDATE t INDEXED BY idx SET a = 2 WHERE a = 1;

UPDATE OR IGNORE t AS x NOT INDEXED SET a = 2 WHERE x.a = 1;

DELETE FROM t INDEXED BY idx WHERE a = 1;

DELETE FROM main.t NOT INDEXED WHERE a = 1;
